# 36 beauty brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes)
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
# Skincare
("estee-lauder","Estée Lauder","https://www.esteelauder.com/","Estée Lauder and her husband Joseph founded the company in New York in 1946.","Thin, light capitals in dark navy make the name feel calm and expensive.","A bar over the second E replaces the accent, a small detail that makes the wordmark recognisable."),
("la-mer","La Mer","https://www.cremedelamer.com/","Crème de la Mer launched in 1965, and Estée Lauder bought the brand in 1995.","Classic serif capitals look like they were carved in stone.","Two short words in black are the whole logo, which suits a cream that costs hundreds of dollars."),
("la-roche-posay","La Roche-Posay","https://www.laroche-posay.us/","La Roche-Posay was founded in 1975, is named after a French spa town and has been owned by L'Oréal since 1989.","A blue square behind the E is the only colour, like a label on a pharmacy shelf.","The line \"Laboratoire Dermatologique\" underneath tells you it is a skincare lab, not a fashion brand."),
("cerave","CeraVe","https://www.cerave.com/","CeraVe launched in 2005, and L'Oréal bought it in 2017.","The name is split in two: navy Cera and white Ve inside a bright blue box.","The line \"Developed with dermatologists\" sits under the name and supports the clinical tone."),
("the-ordinary","The Ordinary","https://theordinary.com/en-us","DECIEM launched The Ordinary in Toronto in 2016.","A small \"The\" sits above a heavier \"Ordinary\", so the important word does the work.","The full stop makes the name sound like a plain statement, which fits a brand built on simple, cheap formulas."),
("drunk-elephant","Drunk Elephant","https://www.drunkelephant.com/","Tiffany Masterson founded Drunk Elephant in Houston in 2012, and Shiseido bought it in 2019.","Widely spaced grey serif capitals are quiet compared with the brand's bright packaging.","The playful name does the talking, so the logo itself stays very simple."),
("glow-recipe","Glow Recipe","https://www.glowrecipe.com/","Sarah Lee and Christine Chang founded Glow Recipe in 2014.","Heavy, rounded capitals look friendly and modern.","The logo is all black, while the colour comes from the fruit-inspired packaging."),
("tatcha","Tatcha","https://www.tatcha.com/","Vicky Tsai founded Tatcha in San Francisco in 2009, and Unilever bought it in 2019.","Thin geometric capitals are spaced very far apart.","The airy spacing gives the short name a calm, luxurious feel."),
("aesop","Aesop","https://www.aesop.com/us/","Dennis Paphitis founded Aesop in Melbourne in 1987, and L'Oréal bought it in 2023.","An elegant serif in lowercase looks like a book title.","A bar over the e is the one unusual detail and makes the name feel literary."),
# Makeup
("fenty-beauty","Fenty Beauty","https://fentybeauty.com/","Rihanna launched Fenty Beauty in 2017 with Kendo, part of LVMH.","Bold capitals are spaced so wide that the name reads almost like a pattern.","The N in Fenty is flipped, a small twist that makes the logo feel bold and different."),
("rare-beauty","Rare Beauty","https://www.rarebeauty.com/","Selena Gomez launched Rare Beauty in 2020.","A deep plum colour makes the logo warmer than the usual black.","Rounded, friendly letters match the brand's message about self-acceptance."),
("glossier","Glossier","https://www.glossier.com/","Emily Weiss launched Glossier in New York in 2014, growing it out of her blog Into the Gloss.","A heavy italic gives the name energy and confidence.","The full stop at the end is part of the brand, as if the name were a short sentence."),
("mac-cosmetics","MAC Cosmetics","https://www.maccosmetics.com/","Frank Toskan and Frank Angelo founded MAC in Toronto in 1984, and Estée Lauder has fully owned it since 1998.","Three letters are stretched so wide that they become thin lines.","The extreme width makes the logo instantly recognisable on a black compact."),
("nars","NARS","https://www.narscosmetics.com/","François Nars launched NARS in New York in 1994 with 12 lipsticks sold at Barneys.","Thin letters overlap each other, so the four letters become one shape.","Every stroke has the same weight, which makes the mark look like a fashion monogram."),
("charlotte-tilbury","Charlotte Tilbury","https://www.charlottetilbury.com/us","Makeup artist Charlotte Tilbury launched her brand in London in 2013.","First name and surname are joined without a space, like a signature.","Dark brown ink feels softer and more glamorous than black."),
("benefit-cosmetics","Benefit Cosmetics","https://www.benefitcosmetics.com/","Twin sisters Jean and Jane Ford opened their first shop in San Francisco in 1976, and Benefit is now owned by LVMH.","A friendly lowercase serif makes the brand feel approachable.","The f has a long swash, a playful flourish in an otherwise simple wordmark."),
("maybelline","Maybelline","https://www.maybelline.com/","Thomas Lyle Williams founded Maybelline in 1915 and named it after his sister Mabel.","Widely spaced black capitals look clean and modern.","\"New York\" sits under the name, linking a mass-market brand to the city's style."),
("huda-beauty","Huda Beauty","https://hudabeauty.com/","Huda Kattan launched Huda Beauty in Dubai in 2013, starting with false lashes.","Heavy \"huda\" and light \"beauty\" split the name by weight, not by space.","All-lowercase letters make the brand feel personal, like the founder's own name."),
# Fragrance
("chanel","Chanel","https://www.chanel.com/us/","Gabrielle Chanel opened her first shop in Paris in 1910, and Chanel No. 5 followed in 1921.","Wide, geometric capitals in black give the name a strong, timeless shape.","The wordmark is often paired with the interlocking CC monogram on bottles."),
("dior","Dior","https://www.dior.com/en_us","Christian Dior founded his house in Paris in 1946 and launched Miss Dior perfume in 1947.","A tall capital D towers over the lowercase letters.","Strong contrast between thick and thin strokes makes the serif look elegant."),
("yves-saint-laurent","Yves Saint Laurent","https://www.yslbeautyus.com/","Yves Saint Laurent and Pierre Bergé founded the house in Paris in 1961, and YSL Beauty has been part of L'Oréal since 2008.","Tall, condensed letters overlap and share strokes.","Long tails on the Y, S and L tie the three names together."),
("tom-ford","Tom Ford","https://www.tomfordbeauty.com/","Tom Ford launched his own brand in 2005, and Estée Lauder bought the Tom Ford brand in 2023.","Heavy black capitals are set so tightly that they almost touch.","The tight spacing makes the logo look solid and confident, like a men's tailoring label."),
("jo-malone-london","Jo Malone London","https://www.jomalone.com/","Jo Malone opened her first shop in London in 1994, and Estée Lauder bought the brand in 1999.","Wide serif capitals for the name sit over a small, spaced \"London\".","The layout looks like a classic British label, which suits the cream-and-black boxes."),
("diptyque","Diptyque","https://www.diptyqueparis.com/en_us","Three friends opened the first Diptyque shop at 34 boulevard Saint-Germain in Paris in 1961.","Serif capitals with sharp details look like an old Parisian shop sign.","\"Paris\" below the name ties the brand to its home city."),
("le-labo","Le Labo","https://www.lelabofragrances.com/","Le Labo opened in New York in 2006, and Estée Lauder bought it in 2014.","Heavy capitals with a rough, stamped texture look printed by hand.","The line \"Grasse – New York\" connects the French perfume capital with the brand's home."),
("byredo","Byredo","https://www.byredo.com/us_en","Ben Gorham founded Byredo in Stockholm in 2006, and Puig bought it in 2022.","Each letter is cut into pieces, so the name looks like a stencil.","The custom lettering feels more like an art project than a perfume label."),
("guerlain","Guerlain","https://www.guerlain.com/us/en-us/","Pierre-François-Pascal Guerlain founded the house in Paris in 1828, and it has been part of LVMH since 1994.","Wide geometric capitals give an old house a modern look.","The round G opens the name with a perfect circle."),
# Hair and body
("olaplex","Olaplex","https://olaplex.com/","Olaplex launched in 2014 with a bond-building treatment first sold to salons.","Heavy, round capitals look strong and technical.","The wide letters fill the space and read well on small bottles."),
("k18","K18","https://www.k18hair.com/","K18 launched in 2020 with a leave-in treatment built on a patented peptide.","Heavy black K18 is short and easy to remember.","A small lavender molecule and the line \"Biomimetic Hairscience\" signal a science-led brand."),
("kerastase","Kérastase","https://www.kerastase-usa.com/","L'Oréal created Kérastase in 1964 as a salon haircare brand.","Thin capitals with a sharp accent on the E look refined and French.","A tiny \"Paris\" below the name adds to the premium salon feel."),
("aveda","Aveda","https://www.aveda.com/","Horst Rechelbacher founded Aveda in Minneapolis in 1978, and Estée Lauder bought it in 1997.","The As have no crossbar, just a dot inside, so they look like small triangles.","The tagline about flower and plant essences sits underneath and explains the brand's focus."),
("briogeo","Briogeo","https://briogeohair.com/","Nancy Twine founded Briogeo in New York in 2013.","A heavy, rounded sans serif makes the unusual name easy to read.","The friendly letters suit a brand that sells clean haircare for many hair types."),
("sol-de-janeiro","Sol de Janeiro","https://soldejaneiro.com/","Sol de Janeiro launched in 2015, and L'Occitane bought it in 2021.","Italic serif capitals with flourishes feel sunny and festive.","A small raised \"de\" between the words gives the name rhythm."),
("dove","Dove","https://www.dove.com/us/en/home.html","Dove launched its beauty bar in the United States in 1957 and is owned by Unilever.","A navy script name looks soft and gentle.","A small gold dove under the name is one of the best-known symbols in personal care."),
("bath-and-body-works","Bath & Body Works","https://www.bathandbodyworks.com/","Bath & Body Works opened its first store in 1990 and is based in Ohio.","Blue lowercase letters make the long name feel light and friendly.","The ampersand joins the two halves of the name in the same thin style."),
("necessaire","Nécessaire","https://necessaire.com/","Nécessaire is a body care brand founded by Randi Christiansen and Nick Axelrod-Welk.","A heavy, condensed serif looks like a newspaper headline.","The accent on the first e is kept, which makes the French name feel authentic."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 36
